def _text_of(message: BaseMessage) -> str:
    """Flatten block-style content down to plain text.

    A reasoning model returns content as a list of blocks (reasoning,
    tool_call, text). ollama's converter only accepts 'text' blocks and
    raises on anything else, so everything else gets dropped here.
    """

    if isinstance(message.content, str):
        return message.content
    parts = []
    for block in message.content:
        if isinstance(block, str):
            parts.append(block)
        elif isinstance(block, dict) and block.get("type") == "text":
            parts.append(block.get("text", ""))
    return "\n".join(parts)


def strip_tool_context(messages: list[BaseMessage]) -> list[BaseMessage]:
    """Strip full context from tool calls.

    Used for cleaning up the first exchange for feeding it
    back into the model to self-name the session.
    """

    cleaned = []
    for m in messages:
        if isinstance(m, ToolMessage):
            continue
        if isinstance(m, AIMessage):
            text = _text_of(m)
            # a pure reasoning + tool_call turn has no text worth keeping
            if not text.strip():
                continue
            cleaned.append(AIMessage(content=text))
        else:
            cleaned.append(m)
    return cleaned

